add_filter( 'wp_nav_menu_items', 'perfectpixel_search_in_menu', 20, 2 );

function perfectpixel_search_in_menu( $items, $args ) {
	if ( empty( $args->theme_location ) || trim( '{{search_menu_location}}' ) !== $args->theme_location ) {
		return $items;
	}
	$form = sprintf(
		'<form role="search" method="get" action="%s" class="perfectpixel-menu-search"><input type="search" name="s" placeholder="%s" aria-label="%s" style="max-width:12em"><input type="hidden" name="post_type" value="product"></form>',
		esc_url( home_url( '/' ) ),
		esc_attr( '{{search_menu_placeholder}}' ),
		esc_attr( '{{search_menu_placeholder}}' )
	);
	return $items . '<li class="menu-item perfectpixel-menu-search-item">' . $form . '</li>';
}
